#[test]
fn parse_fuzz_seed_1_never_panics_and_refuses_every_other_windo() {
    let mut rng = Rng::new(104729);
    for _ in 0..3000 {
        let message = rng.text(&["settings:", "together:", "cast:", "stream:", "media:", "mini:", "player:", "lock:", "drag", "resize:", "service:", "open-url:", "lang:", "viewport:", "opacity:", "ext-toggle:", "page-check:", "media-state:"]);
        if let Some(command) = parse(&message) {
            for foreign in ["together:", "cast:", "stream:", "mini:", "player:", "lock:"] {
                assert!(!message.starts_with(foreign), "{message:?} → {command:?}");
            }
        }
    }
}

