#[test]
fn parse_refuses_overlong_media_and_page_reports() {
    let media = format!("media-state:{{\"title\":\"{}\"}}", "x".repeat(crate::media::MAX_REPORT_BYTES));
    assert_eq!(parse(&media), None);
    let page = format!("page-check:{{\"site\":\"google\",\"page\":\"sign-in-refused\",\"x\":\"{}\"}}", "y".repeat(600));
    assert_eq!(parse(&page), None);
}

#[test]
fn is_extension_id_knows_exactly_32_letters_from_a_to_p() {
    for c in b'a'..=b'p' {
        assert!(is_extension_id(&(c as char).to_string().repeat(32)));
    }
    for c in *b"qzA0-_" {
        assert!(!is_extension_id(&(c as char).to_string().repeat(32)));
    }
    assert!(!is_extension_id(""));
}
